customCSS.value:
.registration-body { box-sizing: border-box; width: 600px; background-color: rgba(255, 255, 255, 0.97); max-width: 100%; border-radius: 7px; box-shadow: 1px 1px 1px 1px rgba(0, 0, 0, 0.1); padding: 30px 70px 35px; transition: opacity 0.5s; }

.registration-logo { text-align: center; }
.registration-logo img { max-width: 450px; max-height: 100px; }

.registration-title { margin-bottom: 25px; text-align: center; color: #6b6b6b; font-size: 32px; line-height: 1em; font-family: "ProximaNovaRegular", helvetica, arial, sans-serif; padding: 50px 0 0; }

.registration-body-txt { font-size: 18px; line-height: 1.3em; color: #6b6b6b; }

.registration-buttons { margin: 30px auto 0 auto; text-align: center; }
.registration-buttons .button { margin: 0; }
.registration-buttons .skip-btn { margin-top: 25px; }

.registration .footer { position: fixed; bottom: 10px; right: 0; left: 0; text-align: center; }

.registration .footer .pingid_logo { display: block; width: 70px; height: 27px; background-image: url(../images/pingid/ping-logo.sm.2x.png); background-size: 70px 27px; margin: 40px auto 15px auto; }

.registration .footer .copyright { font-size: 12px; color: #999999; }

.flex-content__scroller {
    max-width: 100%;
    max-height: 100%;
    overflow-y: auto;
}
.flex-content {
    position: fixed;
    top: 0;
    bottom: 0;
    left: 0;
    right: 0;
    z-index: 1000;
    min-height: 100%;
    align-items: center;
    justify-content: center;
    display: -webkit-box;
    display: -webkit-flex;
    display: -moz-flex;
    display: -ms-flexbox;
    display: flex;
}
.button {
    padding: 0 25px;
    margin-right: 10px;
    height: 36px;
    line-height: 36px;
    box-sizing: border-box;
    -webkit-border-radius: 2px;
    -moz-border-radius: 2px;
    -ms-border-radius: 2px;
    border-radius: 2px;
    font-size: 15px;
    font-family: "ProximaNovaRegular", helvetica, arial, sans-serif;
    position: relative;
    display: inline-block;
    text-align: center;
    vertical-align: middle;
    cursor: pointer;
    outline: none;
    white-space: nowrap;
    color: #fff;
    border: none;
    background: none;
    background-color: #2996cc;
    width: auto;
}

.button:hover {
    color: #fff;
    background-color: #3ea1d1;
}
.flex-content__scroller {
    animation: fadeInAnimation ease 2s;
    animation-iteration-count: 1;
    animation-fill-mode: forwards;

 }
 @keyframes fadeInAnimation {
    0% {
        opacity: 0;
    }
    100% {
        opacity: 1;
    }
}

body {
 background-size: cover !important;
}

customScript.value:
function getThemeByName(templateName, themes) {
  return themes.find(theme => theme.name === templateName) || null;
}

function setBodyBackgroundColor(color) {
  const styleSheet = document.createElement("style");
  styleSheet.innerHTML = `body { background-color: ${color} !important; }`;
  document.head.appendChild(styleSheet);
}

// Apply styles
function applyStyles(theme, themes) {
  const config = JSON.parse(theme);
  const configuration = config?.configuration;
  const templateName = config?.template;
  const allThemes = JSON.parse(themes);
  const template = allThemes.find(theme => theme.name === templateName) || null;
  if (configuration && template)
  {
    const backgroundImageUrl = configuration.backgroundImage?.href || template.image?.background;
    const logo = configuration.logo?.href;

    // Change backgroung image
    if (backgroundImageUrl) {
      document.body.style.backgroundImage = `url('${backgroundImageUrl}')`;
      document.body.style.backgroundRepeat = "repeat";
    }

    if (configuration.backgroundType === "COLOR") {
      document.body.style.backgroundImage = "none";
      setBodyBackgroundColor(configuration.backgroundColor);
    }

    if (configuration.backgroundType === "NONE") {
      document.body.style.backgroundImage = "none";
    }

    // Find an image element inside an element with class 'registration-logo' and change its src to logo.href
    const registrationLogoContainer = document.querySelector('.registration-logo');
    if (registrationLogoContainer) {
      const imgElement = registrationLogoContainer.querySelector('img');
        if (logo && imgElement) {
          imgElement.src = logo;
        }
    }

    // Change all button styles
    const buttons = document.querySelectorAll('button');
    buttons.forEach(btn => {
      btn.style.color = configuration.buttonTextColor || template.color?.buttonText;
      btn.style.backgroundColor = configuration.buttonColor || template.color?.button;
    });

    // Change card color
    const registrationContainer = document.querySelector('.registration-body');
    if (registrationContainer) {
      registrationContainer.style.backgroundColor = configuration.cardColor || template.color?.card;
    }

    // Change title color
    const registrationTitle = document.querySelector('.registration-title');
    if (registrationTitle) {
      registrationTitle.style.color = configuration.headingTextColor || template.color?.headingText;
    }

    // Change text color
    const registrationText = document.querySelector('.registration-body-txt');
    if (registrationText) {
      registrationText.style.color = configuration.bodyTextColor || template.color?.bodyText;
    }

  }
}

// Run the function to apply styles
applyStyles('{{{skjson theme}}}', '{{{skjson themes}}}');

